() => {
  const c = document.querySelector('#canvas_minipaint');
  const before = { w: c.width, h: c.height, cssW: Math.round(c.getBoundingClientRect().width), cssH: Math.round(c.getBoundingClientRect().height) };
  // click zoom out button in preview details (-)
  const btns = [...document.querySelectorAll('.canvas_preview_details button')];
  const minus = btns.find(b => b.textContent.trim() === '-');
  const plus = btns.find(b => b.textContent.trim() === '+');
  if (minus) minus.click();
  const after = { w: c.width, h: c.height, cssW: Math.round(c.getBoundingClientRect().width), cssH: Math.round(c.getBoundingClientRect().height) };
  return { before, after, buttons: btns.map(b=>b.textContent.trim()) };
}

