() => {
  const out = {};
  out.localStorageKeys = Object.keys(localStorage);
  // Try Quick Save (F9)
  const before = { ...localStorage };
  try {
    const ev = new KeyboardEvent('keydown', { key: 'F9', code: 'F9', bubbles: true });
    document.dispatchEvent(ev);
  } catch(e) { out.err = String(e); }
  out.afterKeys = Object.keys(localStorage);
  out.beforeKeys = Object.keys(before);
  // show a sample value
  const k = Object.keys(localStorage)[0];
  if (k) out.sample = { key: k, value: localStorage.getItem(k)?.slice(0, 600) };
  return out;
}

() => {
  const out = {};
  // Look for any exposed global API / config
  out.windowKeys = Object.keys(window).filter(k => /mini|paint|app|config|file|layer/i.test(k)).slice(0,40);
  // Is there a FileSaver / saveAs?
  out.hasSaveAs = typeof window.saveAs;
  out.hasURL = typeof URL.createObjectURL;
  // Check the download helper names present in bundle via anchors
  out.aDownload = [...document.querySelectorAll('a[download]')].map(a=>a.download);
  return out;
}

() => {
  const out = {};
  const safe = (o) => { try { return Object.keys(o).slice(0,60); } catch { return 'n/a'; } };
  out.FileSave = safe(window.FileSave);
  out.FileOpen = safe(window.FileOpen);
  out.AppConfig = safe(window.AppConfig);
  out.Layers = safe(window.Layers);
  // save method signatures
  out.saveMeths = window.FileSave ? Object.getOwnPropertyNames(window.FileSave).concat(Object.getOwnPropertyNames(Object.getPrototypeOf(window.FileSave)||{})).slice(0,40) : null;
  return out;
}

() => {
  const out = {};
  out.SAVE_TYPES = window.FileSave.SAVE_TYPES;
  out.default_extension = window.FileSave.default_extension;
  out.ZOOM = window.AppConfig.ZOOM;
  out.WIDTH = window.AppConfig.WIDTH;
  out.HEIGHT = window.AppConfig.HEIGHT;
  out.visible = { w: window.AppConfig.visible_width, h: window.AppConfig.visible_height };
  out.LANG = window.AppConfig.LANG;
  return out;
}

() => {
  // Build a projection of a real export to learn the schema without dumping megabytes
  const orig = window.FileSave.export_as_json;
  let captured = null;
  window.FileSave.export_as_json = function(...args) {
    const res = orig.apply(this, args);
    captured = res;
    return res;
  };
  try { window.FileSave.export_as_json(true); } catch (e) { return { err: String(e) }; }
  window.FileSave.export_as_json = orig;
  if (!captured) return 'no capture';
  const s = typeof captured === 'string' ? captured : JSON.stringify(captured);
  let parsed = null;
  try { parsed = JSON.parse(s); } catch {}
  return {
    len: s.length,
    head: s.slice(0, 500),
    keys: parsed ? Object.keys(parsed) : null,
    layersType: parsed ? (Array.isArray(parsed.layers) ? 'array['+parsed.layers.length+']' : typeof parsed.layers) : null,
    layer0Keys: parsed && parsed.layers && parsed.layers[0] ? Object.keys(parsed.layers[0]) : null,
    layer0Sample: parsed && parsed.layers && parsed.layers[0] ? JSON.stringify(parsed.layers[0]).slice(0,400) : null,
  };
}

