async (page) => {
  // draw on the main canvas
  const c = page.locator('#canvas_minipaint');
  const box = await c.boundingBox();
  await page.mouse.move(box.x + 50, box.y + 50);
  await page.mouse.down();
  for (let i=0;i<15;i++) await page.mouse.move(box.x+50+i*8, box.y+50+Math.sin(i)*25);
  await page.mouse.up();
  await page.waitForTimeout(200);
  const res = await page.evaluate(() => {
    const s = window.FileSave.export_as_json(true);
    const p = JSON.parse(s);
    return { len: s.length, dataLen: Array.isArray(p.data)?p.data.length:'n/a',
      layer0Data: p.layers[0].data ? String(p.layers[0].data).slice(0,60) : p.layers[0].data,
      info: p.info };
  });
  return JSON.stringify(res);
}

