    id: rt.id,
    name: rt.name,
    visible: rt.visible,
    opacity: rt.opacity,
    x: rt.x,
    y: rt.y,
    pixels: (() => {
      const c = rt.canvas.getContext("2d", { willReadFrequently: true })!;
      return c.getImageData(0, 0, rt.canvas.width, rt.canvas.height);
    })(),
  }));
  return { layers, activeId: activeLayerId, width: W, height: H };
