      c.getContext("2d", { willReadFrequently: true })!.putImageData(l.pixels, 0, 0);
      layerRefs.current.set(l.id, {
        id: l.id,
        name: l.name,
        visible: l.visible,
        opacity: l.opacity,
        x: l.x,
        y: l.y,
        canvas: c,
      });
