      emboss: (l) =>
        applyToActive((d) => {
          const { width: w, height: h, data: p } = d;
          const copy = new Uint8ClampedArray(p);
          const k = [-2, -1, 0, -1, 1, 1, 0, 1, 2];
          for (let y = 1; y < h - 1; y++)
            for (let x = 1; x < w - 1; x++) {
              let r = 0, g = 0, b = 0;
              let n = 0;
              for (let dy = -1; dy <= 1; dy++)
                for (let dx = -1; dx <= 1; dx++) {
                  const i = ((y + dy) * w + (x + dx)) * 4;
                  const kk = k[n++];
                  r += copy[i] * kk; g += copy[i + 1] * kk; b += copy[i + 2] * kk;
                }
