        const disp = displayRef.current!;
        const d = disp.getContext("2d", { willReadFrequently: true })!.getImageData(Math.floor(pt.x), Math.floor(pt.y), 1, 1).data;
        setColor(rgbToHex(d[0], d[1], d[2]));
