/** Shared file-name + format picker used by both "Save as" and "Export". */
function FileDialogBody({
  editor,
  title,
  showProject,
  onConfirm,
}: {
  editor: EditorApi;
  title: string;
  showProject: boolean;
  onConfirm: (name: string, type: string) => void;
}) {
  const [name, setName] = useState(editor.layers.find((l) => l.id === editor.activeLayerId)?.name ?? "Brush #1");
  const options = useMemo(
    () => (showProject ? [PROJECT_TYPE, ...SAVE_TYPES] : SAVE_TYPES),
    [showProject]
  );
  const [type, setType] = useState(showProject ? PROJECT_TYPE.value : SAVE_TYPES[0].value);
  const [showSize, setShowSize] = useState(true);

  /* estimated size of whichever document the current selection produces */
  const size = useMemo(() => {
    if (type === "JSON") return formatBytes(new Blob([editor.buildProjectJson()]).size);
    try {
      const fmt = type === "JPG" || type === "BMP" ? "image/png" : `image/${type.toLowerCase()}`;
      const url = editor.renderFlattened().toDataURL(fmt);
      const b64 = url.split(",")[1] ?? "";
      return formatBytes(Math.round((b64.length * 3) / 4));
    } catch {
      return "n/a";
    }
  }, [type, editor]);

  return (
    <>
      <table>
        <tbody>
          <tr>
            <th scope="row">File name:</th>
            <td>
              <input type="text" aria-label="File name:" value={name} onChange={(e) => setName(e.target.value)} />
            </td>
          </tr>
          <tr>
            <th scope="row">Save as type:</th>
            <td>
              <div className="mp-radio-group bordered" role="radiogroup" aria-label="Save as type:">
                {options.map((o) => (
                  <label key={o.value}>
                    <input
                      type="radio"
                      name={`${title}-type`}
                      value={o.value}
                      checked={type === o.value}
                      onChange={() => setType(o.value)}
                    />
                    {o.label}
                  </label>
                ))}
              </div>
            </td>
          </tr>
          {showProject && (
            <>
              <tr>
                <th scope="row">File size:</th>
                <td>{size}</td>
              </tr>
              <tr>
                <th scope="row">Resolution:</th>
                <td>{editor.resolution}</td>
              </tr>
              <tr>
                <th scope="row">Show file size:</th>
                <td>
                  <input
                    type="checkbox"
                    aria-label="Toggle"
                    checked={showSize}
                    onChange={(e) => setShowSize(e.target.checked)}
                  />
                </td>
              </tr>
            </>
          )}
        </tbody>
      </table>
      <footer>
        <button type="button" className="mp-dialog-btn" onClick={() => onConfirm(name, type)}>
          Ok
        </button>
        <button type="button" className="mp-dialog-btn" onClick={editor.closeDialog}>
          Cancel
        </button>
      </footer>
    </>
  );
}

function SaveAsBody({ editor }: { editor: EditorApi }) {
  return (
    <FileDialogBody
      editor={editor}
      title="Save as"
      showProject
      onConfirm={(name, type) => {
        if (type === "JSON") editor.saveProject(name);
        else editor.exportImage(type.toLowerCase(), name);
        editor.closeDialog();
      }}
    />
  );
}

function ExportBody({ editor }: { editor: EditorApi }) {
  return (
    <FileDialogBody
      editor={editor}
      title="Export"
      showProject={false}
      onConfirm={(name, type) => {
        editor.exportImage(type.toLowerCase(), name);
        editor.closeDialog();
      }}
    />
  );
}

