async (page) => {
  // Intercept anchor clicks and Quick Save storage before triggering Save As > Ok
  await page.evaluate(() => {
    window.__captured = null;
    const orig = HTMLAnchorElement.prototype.click;
    HTMLAnchorElement.prototype.click = function() {
      window.__captured = { download: this.download, hrefPrefix: String(this.href).slice(0, 40), len: String(this.href).length };
    };
  });
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Save As")').first().click();
  await page.waitForTimeout(200);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(300);
  const cap = await page.evaluate(() => window.__captured);
  // Now test quick save
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Quick Save")').first().click();
  await page.waitForTimeout(300);
  const qs = await page.evaluate(() => {
    const raw = localStorage.getItem('quicksave_data');
    if (!raw) return null;
    const p = JSON.parse(raw);
    return { len: raw.length, info: p.info, layerCount: p.layers.length, layer0: p.layers[0] };
  });
  return JSON.stringify({ cap, qs });
}

