async (page) => {
  const c = page.locator('.mp-canvas-stage canvas');
  const box = await c.boundingBox();
  await page.mouse.move(box.x + 40, box.y + 40);
  await page.mouse.down();
  for (let i=0;i<12;i++) await page.mouse.move(box.x+40+i*10, box.y+40+Math.sin(i)*25);
  await page.mouse.up();
  await page.waitForTimeout(200);
  await page.evaluate(() => {
    window.__cap = null;
    HTMLAnchorElement.prototype.click = function() {
      window.__cap = { download: this.download, href: String(this.href) };
    };
  });
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Save As")').first().click();
  await page.waitForTimeout(150);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(300);
  const res = await page.evaluate(() => {
    const href = window.__cap?.href || '';
    const json = decodeURIComponent(href.split(',').slice(1).join(','));
    const p = JSON.parse(json);
    return { download: window.__cap?.download, len: json.length, layer0Data: String(p.layers[0].data).slice(0,70) };
  });
  return JSON.stringify(res);
}

