async (page) => {
  const errs = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: '+e.message));
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(400);
  // draw
  const c = page.locator('.mp-canvas-stage canvas');
  const box = await c.boundingBox();
  await page.mouse.move(box.x + 50, box.y + 50);
  await page.mouse.down();
  for (let i=0;i<15;i++) await page.mouse.move(box.x+50+i*9, box.y+50+Math.sin(i/2)*28);
  await page.mouse.up();
  await page.waitForTimeout(200);
  const drawnW = await page.evaluate(() => { const x=document.querySelector('.mp-canvas-stage canvas'); return {w:x.width,h:x.height}; });
  // zoom out 2 steps
  await page.locator('.mp-mini-btn').first().click();
  await page.locator('.mp-mini-btn').first().click();
  await page.waitForTimeout(300);
  const zoomedW = await page.evaluate(() => { const x=document.querySelector('.mp-canvas-stage canvas'); return {w:x.width,h:x.height, label:document.querySelectorAll('.mp-mini-btn')[1].textContent, doc:document.body.innerText.match(/\d+ x \d+ px/)?.[0]}; });
  // undo
  await page.keyboard.press('Control+z');
  await page.waitForTimeout(200);
  // redo
  await page.keyboard.press('Control+y');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/verify-final.png', scale: 'css' });
  return JSON.stringify({ errs, drawnW, zoomedW });
}

