async (page) => {
  const out = [];
  for (const [w,h] of [[1920,1080],[1440,900],[1024,768],[780,402],[375,812]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.goto('http://localhost:4173', { waitUntil: 'load' });
    await page.waitForTimeout(600);
    const r = await page.evaluate(() => {
      const c = document.querySelector('.mp-canvas-stage canvas');
      return { doc: document.body.innerText.match(/\d+ x \d+ px/)?.[0], canvasW: c?.width, canvasH: c?.height };
    });
    out.push({ vp:[w,h], ...r });
  }
  return JSON.stringify(out);
}

